"""Generates the section illustrations assets/img/art-*.svg (blue theme). Run: python tools/make_art.py"""
import os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "assets", "img")
B, C, W, M = "#4c7dff", "#22d3ee", "#eef2fb", "#9aa7c2"
def frame(body, id_):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 280" role="img" aria-hidden="true"><defs><linearGradient id="bg{id_}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0c1630"/><stop offset="1" stop-color="#08101f"/></linearGradient><radialGradient id="gl{id_}" cx=".85" cy=".1" r=".7"><stop offset="0" stop-color="{B}" stop-opacity=".45"/><stop offset="1" stop-color="{B}" stop-opacity="0"/></radialGradient><pattern id="dt{id_}" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.1" fill="#fff" fill-opacity=".08"/></pattern></defs><rect width="560" height="280" rx="18" fill="url(#bg{id_})"/><rect width="560" height="280" rx="18" fill="url(#dt{id_})"/><rect width="560" height="280" rx="18" fill="url(#gl{id_})"/>{body}</svg>'''
def win(x, y, w, h, lines=(), title=""):
    s = f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="10" fill="#0d1424" stroke="#26365c"/><circle cx="{x+14}" cy="{y+14}" r="4" fill="#ff5f56"/><circle cx="{x+28}" cy="{y+14}" r="4" fill="#ffbd2e"/><circle cx="{x+42}" cy="{y+14}" r="4" fill="#27c93f"/>'
    if title: s += f'<text x="{x+w/2}" y="{y+18}" text-anchor="middle" font-family="monospace" font-size="10" fill="{M}">{title}</text>'
    for i, (indent, ln, col) in enumerate(lines):
        s += f'<rect x="{x+14+indent*12}" y="{y+34+i*14}" width="{ln}" height="6" rx="3" fill="{col}" fill-opacity=".85"/>'
    return s
def bars(x, y, vals, w=22, g=10, h=100, col=B):
    s = ""; m = max(vals)
    for i, v in enumerate(vals):
        bh = v / m * h; s += f'<rect x="{x+i*(w+g)}" y="{y+h-bh}" width="{w}" height="{bh}" rx="4" fill="{col if i%3 else C}" fill-opacity=".9"/>'
    return s
def line(x, y, vals, w=300, h=100):
    m = max(vals); pts = [(x + i * w / (len(vals) - 1), y + h - v / m * h) for i, v in enumerate(vals)]
    d = "M" + " L".join(f"{a:.0f} {b:.0f}" for a, b in pts)
    return f'<path d="{d} L{x+w} {y+h} L{x} {y+h}Z" fill="{B}" fill-opacity=".18"/><path d="{d}" fill="none" stroke="{C}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>' + "".join(f'<circle cx="{a:.0f}" cy="{b:.0f}" r="4" fill="{W}"/>' for a, b in pts[-3:])
def node(x, y, r=14, col=B): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="#0d1424" stroke="{col}" stroke-width="2.5"/><circle cx="{x}" cy="{y}" r="{r/3}" fill="{col}"/>'
def edge(a, b): return f'<path d="M{a[0]} {a[1]} L{b[0]} {b[1]}" stroke="{B}" stroke-opacity=".5" stroke-width="2"/>'
A = {}
A["portfolio"] = win(40, 40, 250, 130, [(0, 90, C), (1, 140, W), (1, 110, B), (1, 160, W), (0, 60, C), (1, 120, B)], "index.html") + win(250, 110, 270, 130, [(0, 80, B), (1, 150, W), (1, 100, C), (1, 170, W), (1, 90, B)], "growth.js") + line(60, 190, [2, 3, 3, 5, 4, 7, 8, 11, 13], 150, 50)
A["about"] = f'<circle cx="150" cy="120" r="62" fill="#0d1424" stroke="{B}" stroke-width="4"/><circle cx="150" cy="105" r="22" fill="{B}" fill-opacity=".8"/><path d="M104 168 Q150 120 196 168 Z" fill="{B}" fill-opacity=".8"/>' + win(250, 50, 270, 70, [(0, 60, C), (0, 200, W), (0, 150, M)], "profile.json") + win(250, 140, 270, 90, [(0, 100, B), (1, 180, W), (1, 120, C), (0, 80, B)], "skills.json")
A["skills"] = "".join(edge(a, b) for a, b in [((280, 140), (160, 70)), ((280, 140), (400, 70)), ((280, 140), (160, 210)), ((280, 140), (400, 210)), ((160, 70), (80, 140)), ((400, 70), (480, 140)), ((160, 210), (80, 140)), ((400, 210), (480, 140))]) + node(280, 140, 26, C) + "".join(node(x, y) for x, y in [(160, 70), (400, 70), (160, 210), (400, 210), (80, 140), (480, 140)]) + f'<text x="280" y="145" text-anchor="middle" font-family="monospace" font-size="13" fill="{W}">DK</text>'
A["projects"] = win(40, 40, 200, 110, [(0, 70, C), (1, 120, W), (1, 90, B), (0, 40, C)], "App.java") + win(170, 110, 200, 120, [(0, 60, B), (1, 130, W), (1, 100, C), (1, 80, W)], "flow") + win(330, 40, 190, 110, [(0, 90, C), (1, 100, W), (1, 120, B)], "tests") + f'<path d="M110 150 L160 130 M370 150 L330 130" stroke="{C}" stroke-width="2" stroke-dasharray="4 4"/>'
A["experience"] = f'<path d="M60 200 H500" stroke="{B}" stroke-width="3"/>' + "".join(f'{node(x,200,11,C if i%2 else B)}<rect x="{x-38}" y="{120-i%2*30}" width="76" height="46" rx="8" fill="#0d1424" stroke="#26365c"/><rect x="{x-28}" y="{132-i%2*30}" width="56" height="6" rx="3" fill="{W}"/><rect x="{x-28}" y="{146-i%2*30}" width="40" height="5" rx="2.5" fill="{M}"/>' for i, x in enumerate([100, 200, 300, 400, 480]))
A["leetcode"] = "".join(f'<rect x="{50+c*26}" y="{50+r*26}" width="20" height="20" rx="4" fill="{[ "#16315f", B, C, "#2b4ea8"][(c*7+r*3+c*r)%4]}" fill-opacity="{.35+((c*5+r*11)%6)/10}"/>' for c in range(13) for r in range(7)) + f'<circle cx="470" cy="150" r="54" fill="none" stroke="#16315f" stroke-width="14"/><path d="M470 96 A54 54 0 1 1 420 168" fill="none" stroke="{C}" stroke-width="14" stroke-linecap="round"/><text x="470" y="156" text-anchor="middle" font-family="monospace" font-weight="bold" font-size="22" fill="{W}">500+</text>'
A["github"] = line(50, 60, [1, 2, 3, 5, 6, 9, 11, 14, 17, 19, 22], 270, 130) + f'<circle cx="440" cy="120" r="56" fill="none" stroke="{B}" stroke-width="12"/><path d="M440 64 A56 56 0 0 1 496 120" fill="none" stroke="{C}" stroke-width="12"/><path d="M496 120 A56 56 0 0 1 400 160" fill="none" stroke="{W}" stroke-width="12" stroke-opacity=".7"/>' + bars(60, 215, [8, 12, 6, 14, 10, 16, 9], 18, 8, 40)
A["tuf"] = f'<circle cx="150" cy="140" r="70" fill="none" stroke="#16315f" stroke-width="18"/><path d="M150 70 A70 70 0 0 1 218 158" fill="none" stroke="{B}" stroke-width="18" stroke-linecap="round"/><text x="150" y="148" text-anchor="middle" font-family="monospace" font-weight="bold" font-size="26" fill="{W}">348</text>' + "".join(f'<rect x="290" y="{70+i*44}" width="220" height="12" rx="6" fill="#16315f"/><rect x="290" y="{70+i*44}" width="{w}" height="12" rx="6" fill="{c}"/>' for i, (w, c) in enumerate([(120, C), (170, B), (80, W)]))
A["youtube"] = f'<rect x="130" y="50" width="300" height="170" rx="16" fill="#0d1424" stroke="#26365c"/><rect x="150" y="70" width="260" height="110" rx="8" fill="#101c3a"/><path d="M262 100 L262 150 L306 125Z" fill="{C}"/><rect x="150" y="194" width="170" height="8" rx="4" fill="{W}"/><rect x="150" y="208" width="110" height="6" rx="3" fill="{M}"/>' + win(40, 190, 80, 60, [(0, 40, B), (0, 50, C)]) + win(440, 200, 90, 55, [(0, 50, C), (0, 40, B)])
A["linkedin"] = f'<rect x="60" y="50" width="440" height="180" rx="14" fill="#0d1424" stroke="#26365c"/><rect x="60" y="50" width="440" height="60" rx="14" fill="{B}" fill-opacity=".35"/><circle cx="130" cy="120" r="34" fill="#0d1424" stroke="{C}" stroke-width="4"/><circle cx="130" cy="112" r="11" fill="{C}"/><path d="M108 140 Q130 114 152 140Z" fill="{C}"/><rect x="190" y="130" width="200" height="9" rx="4" fill="{W}"/><rect x="190" y="150" width="270" height="6" rx="3" fill="{M}"/><rect x="190" y="166" width="240" height="6" rx="3" fill="{M}"/>' + "".join(f'<rect x="{80+i*140}" y="190" width="120" height="26" rx="13" fill="{B}" fill-opacity=".25" stroke="{B}"/>' for i in range(3))
A["papers"] = f'<rect x="170" y="30" width="200" height="220" rx="10" fill="#0d1424" stroke="#26365c"/><rect x="190" y="52" width="160" height="10" rx="5" fill="{W}"/>' + "".join(f'<rect x="190" y="{80+i*18}" width="{150-(i%3)*18}" height="6" rx="3" fill="{M}"/>' for i in range(8)) + f'<rect x="190" y="230" width="60" height="8" rx="4" fill="{C}"/><circle cx="410" cy="190" r="34" fill="{B}" fill-opacity=".25" stroke="{C}" stroke-width="3"/><path d="M394 190 l12 12 l22 -24" fill="none" stroke="{W}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>'
A["achievements"] = f'<path d="M220 60 H340 V120 Q340 170 280 180 Q220 170 220 120Z" fill="{B}" fill-opacity=".35" stroke="{C}" stroke-width="3"/><path d="M220 80 H190 Q190 130 225 135 M340 80 H370 Q370 130 335 135" fill="none" stroke="{C}" stroke-width="3"/><rect x="262" y="180" width="36" height="30" fill="{B}" fill-opacity=".5"/><rect x="236" y="210" width="88" height="14" rx="5" fill="{C}"/>' + "".join(f'<circle cx="{x}" cy="{y}" r="24" fill="#0d1424" stroke="{c}" stroke-width="3"/><path d="M{x-8} {y} l6 7 l11 -13" fill="none" stroke="{c}" stroke-width="3.5" stroke-linecap="round"/>' for x, y, c in [(90, 190, B), (130, 90, C), (470, 190, C), (430, 90, B)])
A["education"] = f'<path d="M280 70 L450 130 L280 190 L110 130Z" fill="{B}" fill-opacity=".4" stroke="{C}" stroke-width="3"/><path d="M180 160 V210 Q280 250 380 210 V160 L280 200Z" fill="#0d1424" stroke="{C}" stroke-width="3"/><path d="M450 130 V210" stroke="{W}" stroke-width="3"/><circle cx="450" cy="216" r="8" fill="{W}"/>'
A["contact"] = f'<rect x="120" y="70" width="320" height="150" rx="14" fill="#0d1424" stroke="#26365c"/><path d="M120 84 L280 170 L440 84" fill="none" stroke="{C}" stroke-width="4" stroke-linejoin="round"/>' + f'<circle cx="460" cy="70" r="20" fill="{B}"/><text x="460" y="76" text-anchor="middle" font-family="monospace" font-weight="bold" font-size="16" fill="#fff">@</text>'
A["growth"] = line(50, 60, [3, 5, 4, 8, 7, 11, 10, 15, 18, 17, 24], 460, 130) + bars(50, 215, [3, 5, 4, 8, 7, 11, 10, 15, 18, 17, 24], 26, 14, 25)
A["opensource"] = f'<path d="M110 60 V220" stroke="{B}" stroke-width="4"/><path d="M110 110 Q170 110 170 150 V170 Q170 200 230 200 H330" fill="none" stroke="{C}" stroke-width="4"/><path d="M110 70 Q200 70 200 100 H400" fill="none" stroke="{W}" stroke-width="4" stroke-opacity=".7"/>' + "".join(node(x, y, 13, c) for x, y, c in [(110, 60, B), (110, 110, B), (110, 220, B), (170, 150, C), (330, 200, C), (400, 100, W)]) + f'<rect x="350" y="150" width="140" height="60" rx="10" fill="#0d1424" stroke="{C}"/><text x="420" y="186" text-anchor="middle" font-family="monospace" font-size="14" fill="{W}">PR #1</text>'
A["engineering"] = A["portfolio"]
for k, v in A.items():
    open(os.path.join(OUT, f"art-{k}.svg"), "w").write(frame(v, k))
print(len(A), "illustrations")
